tool_and_message_events.command:
/bin/bash -lc "cat > dist/presentation.css <<'EOF'
.sheet {
  width: min(560px, calc(100% - 2 * var(--gap)));
  margin: clamp(var(--gap), 5vw, 48px) auto;
  padding: clamp(var(--gap), 4vw, 32px);
  border-radius: var(--radius);
  background: var(--paper);
  line-height: 1.5;
}

.sheet h1 {
  margin: 0 0 6px;
  font-size: clamp(1.5rem, 4vw, 1.75rem);
  line-height: 1.2;
}

.sheet > p {
  margin: 0;
  color: var(--subtle);
}

#prefs {
  margin-top: calc(1.5 * var(--gap));
}

.sheet label {
  display: block;
  margin-bottom: 6px;
  font-weight: 600;
}

.sheet input,
.sheet select {
  display: block;
  width: 100%;
  min-height: 44px;
  padding: 8px 12px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--subtle);
  border-radius: calc(var(--radius) / 2);
}

.sheet label:not(:first-child) {
  margin-top: var(--gap);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: calc(1.5 * var(--gap));
}

.sheet button {
  max-width: 100%;
  min-height: 44px;
  padding: 8px 14px;
  border: 1px solid var(--subtle);
  border-radius: calc(var(--radius) / 2);
  background: var(--paper);
  color: var(--subtle);
  font-weight: 600;
  overflow-wrap: anywhere;
}

.sheet :is([data-primary], #confirm) {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--paper);
}

.sheet button:hover {
  text-decoration: underline;
  text-underline-offset: 0.18em;
}

.sheet :is(input, select, button):focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.sheet [aria-invalid=\"true\"] {
  border-color: var(--danger);
}

.sheet [role=\"alert\"] {
  margin: 12px 0 0;
  color: var(--danger);
  font-size: 0.9375rem;
}

#saved {
  margin-top: calc(1.5 * var(--gap));
  padding-top: 12px;
  border-top: 1px solid var(--line);
  font-size: 0.9375rem;
  overflow-wrap: anywhere;
}

.sheet dialog {
  width: min(440px, calc(100% - 2 * var(--gap)));
  padding: clamp(var(--gap), 4vw, 24px);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

.sheet dialog h2 {
  margin: 0;
  font-size: 1.25rem;
  line-height: 1.25;
}

.sheet dialog p {
  margin: 8px 0 var(--gap);
  color: var(--subtle);
}

#cancel {
  margin-inline-end: 8px;
}
EOF
sha256sum dist/* visit.mjs"

/bin/bash -lc "node --input-type=module <<'EOF'
import { readFileSync, readdirSync } from 'node:fs';
import assert from 'node:assert/strict';
for (const name of readdirSync('visits').filter(name => name.endsWith('.json'))) {
  const {error, timeline} = JSON.parse(readFileSync('visits/' + name));
  assert.equal(error, null);
  console.log(name);
  for (const {action, state} of timeline.slice(1)) {
    const {geometry, fields, status, focus, dialog} = state;
    assert.equal(geometry.viewport, geometry.page);
    const controls = geometry.elements.filter(node => node.tag === 'BUTTON' || node.tag === 'LABEL');
    for (const node of controls) {
      assert.ok(node.x >= 0 && node.x + node.w <= geometry.viewport);
      assert.ok(node.scroll <= node.client);
      if (node.tag === 'BUTTON') assert.ok(node.h >= 44);
    }
    const focused = controls.find(node => node.text === focus.text);
    if (action.op === 'key' && action.key === 'Tab' && focused) assert.equal(focused.outline, 'solid 3px');
    console.log(action.op, action.key ?? action.target ?? state.width, focus, focused?.outline, fields[0]?.value, status, Boolean(dialog.length));
  }
  const stateAfter = index => timeline[index].state;
  if (name.startsWith('6386')) assert.equal(stateAfter(5).dialog.length, 1);
  if (name.startsWith('ad8')) {
    assert.equal(stateAfter(3).fields[0].invalid, 'true');
    assert.equal(stateAfter(3).focus.id, 'email');
    assert.equal(stateAfter(4).fields[0].value, 'ops@example.test');
    assert.equal(stateAfter(6).dialog.length, 1);
    assert.equal(stateAfter(7).dialog.length, 0);
    assert.equal(stateAfter(7).focus.text, 'Review');
    assert.equal(stateAfter(7).status[0], 'ops@example.test / Daily');
    assert.equal(stateAfter(9).status[0], 'duty@example.test / Daily');
  }
}
EOF"

